import {METRICS,analysisHistory,analyticsSummary} from './analytics.mjs';
export function setupAnalyticsUI({getCity,getOverlay,settings,changed,setOverlay}){
 const panel=document.getElementById('city-layers'),body=document.createElement('div');body.id='analysis-options';body.innerHTML=`<div class="panel-label">LIVE CITY ANALYTICS</div><div class="analysis-scale"></div><div id="analysis-range" class="range-labels"></div><p id="analysis-summary"></p><label class="dial">Opacity <output id="analysis-opacity-value">68%</output></label><input id="analysis-opacity" aria-label="Overlay opacity" type="range" min="10" max="100" value="68"><div class="control-grid"><label>Minimum %<input id="analysis-min" aria-label="Minimum percentage of metric scale" type="number" min="0" max="100" value="0"></label><label>Maximum %<input id="analysis-max" aria-label="Maximum percentage of metric scale" type="number" min="0" max="100" value="100"></label></div><label class="dial">Heat radius / hex size<output id="analysis-radius-value">60</output></label><input id="analysis-radius" aria-label="Heat radius or half hexagon radius" type="range" min="15" max="160" value="60"><label class="policy"><input id="analysis-motion" type="checkbox" checked>Animate flows</label><label class="dial">Animation speed<output id="analysis-speed-value">1×</output></label><input id="analysis-speed" aria-label="Flow animation speed" type="range" min=".25" max="3" step=".25" value="1"><label class="dial">Flow playhead <output id="analysis-time-value">0 s</output></label><input id="analysis-time" aria-label="Flow animation playhead" type="range" min="0" max="60" value="0"><label for="analysis-history">Metric snapshot</label><select id="analysis-history"><option value="-1">Live values</option></select><p id="analysis-note" class="micro"></p><button id="analysis-clear">Clear overlay</button>`;panel.append(body);
 const $=id=>document.getElementById(id),apply=()=>{changed();refresh();};
 for(const [name,key,suffix,scale]of [['opacity','opacity','%',.01],['radius','radius','',1],['speed','animationSpeed','×',1],['time','animationTime',' s',1]])$('analysis-'+name).oninput=e=>{settings[key]=+e.target.value*scale;$('analysis-'+name+'-value').textContent=e.target.value+suffix;if(name==='time'){settings.animate=false;$('analysis-motion').checked=false;}apply();};
 for(const key of ['min','max'])$('analysis-'+key).oninput=e=>{const val=+e.target.value;settings[key]=Math.max(0,Math.min(100,Number.isFinite(val)?val:0));if(settings.min>settings.max)settings[key==='min'?'max':'min']=settings[key];$('analysis-min').value=settings.min;$('analysis-max').value=settings.max;apply();};
 $('analysis-motion').onchange=e=>{settings.animate=e.target.checked;apply();};$('analysis-history').onchange=e=>{settings.snapshot=+e.target.value;apply();};$('analysis-clear').onclick=()=>{setOverlay('city');refresh();};
 function refresh(){const c=getCity(),key=getOverlay(),m=METRICS[key];body.hidden=!m;if(!m)return;body.querySelector('.analysis-scale').style.background=['power','water','transit'].includes(key)?'linear-gradient(90deg,#f35951,#fac552,#64e0b1,#2399ae)':'linear-gradient(90deg,#2399ae,#64e0b1,#fac552,#f35951)';$('analysis-range').replaceChildren(...m.range.map(v=>{const span=document.createElement('span');span.textContent=v.toLocaleString()+' '+m.unit;return span;}));$('analysis-summary').textContent=analyticsSummary(c,key,settings);const select=$('analysis-history'),history=analysisHistory(c);select.replaceChildren(new Option('Live values','-1'),...history.map((s,i)=>new Option('Month '+s.month+' · current geometry',i)));select.value=String(settings.snapshot);$('analysis-note').textContent=key==='traffic'?'Animated sample routes follow connected roads and bridges. Congestion is simulated; trails are illustrative.':key==='wind'?'Wind direction is illustrative. Speed and weather follow the current city settings.':key==='load'||['power','water','transit'].includes(key)?'Pulses show connected service, not a hydraulic or electrical flow solution.':key==='carbon'?'Operational CO₂ allocated by tax share; not a measured emissions inventory.':key==='population'?'Relative hotspot density. Radius is in screen pixels; the pattern changes with zoom.':key==='density'?'Residents summed per hexagon; radius is twice the size slider in meters.':'Simulation values update with growth, weather, and policies. The scale stays fixed for comparisons.';}
 return {refresh};
}
